using System;

// Skenario Unit Testing: DiscountCalculator
public class DiscountEngine
{
    public decimal Calculate(decimal totalSpend)
    {
        if (totalSpend < 0) throw new ArgumentOutOfRangeException(nameof(totalSpend), "Total belanja tidak boleh negatif!");
        if (totalSpend >= 1_000_000) return totalSpend * 0.10m; // 10% diskon
        if (totalSpend >= 500_000) return totalSpend * 0.05m;   // 5% diskon
        return 0;
    }
}

// Simulasi Mini Test Runner
public class Program
{
    public static void Main()
    {
        var engine = new DiscountEngine();
        int passed = 0;
        int failed = 0;

        void AssertEqual(decimal expected, decimal actual, string testName)
        {
            if (expected == actual)
            {
                Console.WriteLine($"[PASS] {testName}");
                passed++;
            }
            else
            {
                Console.WriteLine($"[FAIL] {testName} - Ekspektasi: {expected}, Nyata: {actual}");
                failed++;
            }
        }

        // Test 1: Belanja 200k -> Diskon 0
        AssertEqual(0, engine.Calculate(200_000), "Belanja 200k Diskon 0");

        // Test 2: Belanja 500k -> Diskon 25k (5%)
        AssertEqual(25_000, engine.Calculate(500_000), "Belanja 500k Diskon 5%");

        // TODO: Tambahkan Test 3: Belanja 1.000.000 -> Diskon 100.000 (10%)
        // Panggil AssertEqual dengan nilai yang sesuai.

        Console.WriteLine($"\nHasil Tes: {passed} Lulus, {failed} Gagal");
    }
}

